public interface NotificationDeliveryRepository extends JpaRepository<NotificationDelivery,UUID>{Page<NotificationDelivery> findAllByOrganizationId(UUID org,Pageable p);List<NotificationDelivery> findAllByNotificationId(UUID id);boolean existsByNotificationIdAndChannelAndStatusNot(UUID notificationId,NotificationChannel channel,NotificationDeliveryStatus status);List<NotificationDelivery> findTop50ByStatusInAndNextAttemptAtLessThanEqualOrderByNextAttemptAtAscIdAsc(Collection<NotificationDeliveryStatus> statuses,Instant now);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select d from NotificationDelivery d where d.organizationId=:org and d.id=:id")Optional<NotificationDelivery> findForUpdate(@Param("org")UUID org,@Param("id")UUID id);}
